const payload = items[0]?.json ?? {};
const requests = Array.isArray(payload.requests) ? payload.requests : [];

const redFlags = [
  ['homework', 'red:academic_cheating'],
  ['legal advice', 'red:regulated_advice'],
  ['stock trades', 'red:regulated_financial_advice'],
  ['fake reviews', 'red:deceptive_promotion'],
  ['mass dm', 'red:spam_or_bulk_outreach']
];
const yellowFlags = [
  ['texts prospects', 'yellow:automated_outreach_review'],
  ['sms', 'yellow:automated_outreach_review'],
  ['automatically', 'yellow:automation_review']
];

function parseNumber(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function detectRisk(requestText, notes) {
  const haystack = `${requestText} ${notes}`.toLowerCase();
  for (const [term, label] of redFlags) {
    if (haystack.includes(term)) return label;
  }
  for (const [term, label] of yellowFlags) {
    if (haystack.includes(term)) return label;
  }
  return 'green';
}

function scoreRequest(row) {
  const requestText = String(row.request ?? '');
  const notes = String(row.notes ?? '');
  const riskLabel = detectRisk(requestText, notes);
  if (riskLabel.startsWith('red:')) {
    return {
      ...row,
      score: 0,
      priority: 'do_not_pursue',
      risk_label: riskLabel,
      next_step: 'Decline or ignore because the request conflicts with service boundaries.'
    };
  }

  const value = parseNumber(row.value_estimate);
  const lastTouchDays = parseNumber(row.last_touch_days);
  let score = 25;
  if (value >= 1000) score += 35;
  else if (value >= 400) score += 25;
  else if (value >= 250) score += 15;

  if (lastTouchDays >= 14) score += 15;
  else if (lastTouchDays >= 7) score += 10;
  else if (lastTouchDays <= 2) score += 5;

  const lower = requestText.toLowerCase();
  if (lower.includes('zapier') || lower.includes('automation')) score += 15;
  if (lower.includes('quote') || lower.includes('checklist') || lower.includes('staff')) score += 16;
  if (riskLabel.startsWith('yellow:')) score -= 20;

  const priority = score >= 70 && riskLabel === 'green' ? 'high' : 'review_first';
  return {
    ...row,
    score,
    priority,
    risk_label: riskLabel,
    next_step: priority === 'high'
      ? 'Propose a scoped first milestone with sample data, logging, setup notes, and a review gate.'
      : 'Review policy and scope before proposing. Keep human approval gates in place.'
  };
}

const triaged = requests.map(scoreRequest);
const summary = triaged.reduce((acc, row) => {
  acc.total_requests += 1;
  acc[row.priority] = (acc[row.priority] ?? 0) + 1;
  return acc;
}, {total_requests: 0, high: 0, review_first: 0, do_not_pursue: 0});
const actionPlan = triaged
  .filter((row) => row.priority === 'high')
  .map(({id, company, priority, score, risk_label, next_step}) => ({id, company, priority, score, risk_label, next_step}));

return [{json: {summary, action_plan: actionPlan, triaged_requests: triaged}}];
